// eval/tasks/cqe-task14/harness.ts
//
// Auto-generated by eval/lib/importCadQueryEval.ts from
// cadqueryeval/src/cadqueryeval/data/tasks/task14.yaml.
//
// Gates:
//   - evaluates clean (no diagnostics)
//   - non-empty solid (volume > 0)
//   - bbox within tolerance of [120, 60, 25.981] mm (±2 mm or ±5% per axis)
//   - geometry passes cadqueryeval scorer (delegates to the Node wrapper
//     around cadqueryeval's geometry checks; uses reference.stl in the task
//     dir as ground truth)

import { join } from 'node:path';
import { evaluateScript, getShapeInfo } from '../../oracle/kernelcad-client';
import { runCadQueryEvalScorer } from '../../oracle/cadQueryEvalScorer';
import { getStlBbox } from '../../oracle/stlBbox';
import type { HarnessCtx, HarnessResult } from '../../types';

const TARGET_BBOX: [number, number, number] = [120, 60, 25.981];

function axisWithinTolerance(actual: number, target: number): boolean {
  const tol = Math.max(2, Math.abs(target) * 0.05);
  return Math.abs(actual - target) <= tol;
}

export default async function harness(scriptPath: string, ctx?: HarnessCtx): Promise<HarnessResult> {
  const ev = await evaluateScript(scriptPath);
  if (!ev.ok) {
    return { gates: { 'evaluates clean': false }, scored: {} };
  }

  const shape = await getShapeInfo(scriptPath);

  // Use the *meshed* STL extent for the bbox gate — this is what the
  // cadqueryeval scorer and every downstream STL consumer sees. The BREP
  // AABB from get_shape_info can over-report for turned / chamfered parts
  // (see eval/oracle/stlBbox.ts). When ctx is absent (harness called from
  // a unit test without a run dir) we fall back to the BREP AABB.
  let actualExtent: [number, number, number];
  if (ctx) {
    const meshBbox = await getStlBbox(scriptPath, ctx.runDir);
    actualExtent = meshBbox.extent;
  } else {
    actualExtent = [
      shape.bbox.max[0] - shape.bbox.min[0],
      shape.bbox.max[1] - shape.bbox.min[1],
      shape.bbox.max[2] - shape.bbox.min[2],
    ];
  }
  const bboxOk =
    axisWithinTolerance(actualExtent[0], TARGET_BBOX[0]) &&
    axisWithinTolerance(actualExtent[1], TARGET_BBOX[1]) &&
    axisWithinTolerance(actualExtent[2], TARGET_BBOX[2]);

  // Scored field: delegate to the cadqueryeval scorer wrapper. Only meaningful
  // when the runner provides ctx (so we know where reference.stl lives and
  // where to drop intermediate artifacts). We also capture the scorer's
  // detailed metrics (chamfer distance, hausdorff_95p, volume_ratio, ...) and
  // surface them via `metrics` so downstream tools can read `score.json`
  // without re-running the scorer.
  let scorerPassed = false;
  let metrics: Record<string, number | boolean | string | null> | undefined;
  if (ctx) {
    const referencePath = join(ctx.taskDir, 'reference.stl');
    try {
      const result = await runCadQueryEvalScorer(scriptPath, referencePath, ctx.runDir);
      scorerPassed = !!result?.passed;
      metrics = {
        cqe_passed: result.passed,
        cqe_reason: result.reason,
        is_watertight: result.is_watertight,
        is_single_component: result.is_single_component,
        bbox_accurate: result.bbox_accurate,
        volume_passed: result.volume_passed,
        chamfer_passed: result.chamfer_passed,
        hausdorff_passed: result.hausdorff_passed,
        chamfer_distance: result.chamfer_distance,
        hausdorff_95p: result.hausdorff_95p,
        hausdorff_99p: result.hausdorff_99p,
        icp_fitness: result.icp_fitness,
        volume_ratio: result.volume_ratio,
        reference_volume: result.reference_volume,
        generated_volume: result.generated_volume,
        cqe_export_ms: result.exportMs,
        cqe_score_ms: result.scoreMs,
      };
    } catch (err) {
      scorerPassed = false;
      metrics = {
        cqe_passed: false,
        cqe_reason: `scorer threw: ${err instanceof Error ? err.message : String(err)}`,
      };
    }
  }

  return {
    gates: {
      'evaluates clean': true,
      'non-empty solid': shape.volume > 0,
      'bbox within tolerance': bboxOk,
    },
    scored: {
      'geometry passes cadqueryeval scorer': scorerPassed,
    },
    ...(metrics !== undefined ? { metrics } : {}),
  };
}
